import pandas as pd, re
for split in ['train','test']:
    df = pd.read_parquet(f'raw/gsm8k/main/{split}-00000-of-00001.parquet')
    multi=0; first_last_diff=0; examples=[]
    for a in df['answer']:
        nums = re.findall(r'#### (\-?[0-9\.\,]+)', a)
        if len(nums)>1:
            multi+=1
            if nums[0]!=nums[-1]:
                first_last_diff+=1
                if len(examples)<3: examples.append((nums[0], nums[-1], a[-120:]))
    print(f'{split}: answers with >1 #### : {multi}, first!=last : {first_last_diff}')
    for e in examples: print('  ', e)
"

